import { useCommercialSelectOptions } from 'components/Filter/hooks/useCommercialSelectOptions';
import { useQuickFilter } from 'components/Filter/hooks/useQuickFilter';
import {
  isFilterSelectClearableEnabledForPage,
  shouldShowFilterSelectClearIndicator,
} from 'components/Filter/utils/filterClearableSelectPolicy';
import { Select } from 'components/Form';
import { Option } from 'models/Filters';

export const GrowthLeversQuickFilter = ({
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}) => {
  const countryValue = getCurrentValue('country');
  const zoneValue = getCurrentValue('zone');

  const {
    options,
    currentValue,
    handleValueChange,
    handleClear,
    showClearIcon,
    defaults,
  } = useQuickFilter({
    fieldKey,
    pageName,
    gaCategory: 'Growth Levers Select',
    filterContext: { country: countryValue, zone: zoneValue },
    onValueChange,
    getCurrentValue,
  });

  const {
    rawOptions,
    selectableOptions,
    isCommercialPage,
    commercialDisplayValue,
  } = useCommercialSelectOptions({
    pageName,
    rawOptions: options,
    formValue: currentValue,
    defaultValue: defaults?.[fieldKey],
  });

  const displayValue = isCommercialPage ? commercialDisplayValue : currentValue;

  const resolvedShowClearIcon = isFilterSelectClearableEnabledForPage(pageName)
    ? shouldShowFilterSelectClearIndicator(
        pageName,
        fieldKey,
        String(currentValue ?? ''),
        rawOptions,
        defaults,
      )
    : showClearIcon;

  return (
    <Select
      id={`${fieldKey}-select-quick-filter`}
      value={displayValue}
      options={isCommercialPage ? selectableOptions : options}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        handleValueChange(opt as Option);
      }}
      size="medium"
      shape="pill"
      placeholder={isCommercialPage ? 'Select Growth Levers' : ''}
      chips
      clearChips={resolvedShowClearIcon}
      onClearSingle={handleClear}
      valueLabel="Growth Levers"
      searchable
    />
  );
};
